mapper.select:
select
a.defect_id,
a.defect_level,
a.defect_time,
a.defect_type,
a.defect_name,
a.defect_content,
a.device_id,
a.cunstom_id,
a.instance_id,
a.std_mete_id,
a.conf_mode,
a.is_defect,
a.deal_type,
a.deal_info,
a.deal_person_id,
a.deal_time,
a.if_defect_disable,
a.alarm_source,
a.defect_subtype,
a.device_code,
a.image_path,
a.video_path,
a.VALUE,
a.out_range,
a.link_message
from t_defect_info a
where 1 = 1
 and a.defect_id = #{defectId, jdbcType=BIGINT}
 and a.defect_level = #{defectLevel, jdbcType=INTEGER}
 and a.defect_time = #{defectTime, jdbcType=TIMESTAMP}
 and a.defect_type = #{defectType, jdbcType=INTEGER}
 and a.defect_name = #{defectName, jdbcType=VARCHAR}
 and a.defect_content = #{defectContent, jdbcType=VARCHAR}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.cunstom_id = #{cunstomId, jdbcType=VARCHAR}
 and a.instance_id = #{instanceId, jdbcType=BIGINT}
 and a.std_mete_id = #{stdMeteId, jdbcType=BIGINT}
 and a.conf_mode = #{confMode, jdbcType=INTEGER}
 and a.is_defect = #{isDefect, jdbcType=INTEGER}
 and a.deal_type = #{dealType, jdbcType=INTEGER}
 and a.deal_info = #{dealInfo, jdbcType=VARCHAR}
 and a.deal_person_id = #{dealPersonId, jdbcType=VARCHAR}
 and a.deal_time = #{dealTime, jdbcType=TIMESTAMP}
 and a.if_defect_disable = #{ifDefectDisable, jdbcType=INTEGER}
 and a.alarm_source = #{alarmSource, jdbcType=INTEGER}
 and a.defect_subtype = #{defectSubtype, jdbcType=INTEGER}
 and a.device_code = #{deviceCode, jdbcType=VARCHAR}
 and a.image_path = #{imagePath, jdbcType=VARCHAR}
 and a.video_path = #{videoPath, jdbcType=VARCHAR}
 and a.VALUE = #{value, jdbcType=VARCHAR}
 and a.out_range = #{outRange, jdbcType=VARCHAR}
 and a.link_message = #{linkMessage, jdbcType=VARCHAR}

